protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Preserve EF8 discriminator property name ("Discriminator" instead of new "$type" default)
    // so existing documents and raw SQL queries (WHERE c.Discriminator = 'Blog') keep working.
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Preserve EF8 compound id format ("Blog|1") so existing documents remain accessible.
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // HasIndex was removed — Cosmos DB indexing is managed via the container's indexing policy,
    // not EF Core. The EF8 call was silently ignored; EF9 throws at startup.
}

